interface OverlayFsLayer {
  layerId: string;
  isReadOnly: boolean;
  files: Map<string, { sizeKb: number; inode: number; isWhiteout: boolean }>;
}

class OverlayFsStack {
  private lowerLayers: OverlayFsLayer[] = [];
  private upperLayer: OverlayFsLayer;
  private nextInode = 1000;

  constructor(lowerCount: number) {
    for (let i = 0; i < lowerCount; i++) {
      const layer: OverlayFsLayer = {
        layerId: `lower-${i}`,
        isReadOnly: true,
        files: new Map()
      };
      this.lowerLayers.push(layer);
    }
    this.upperLayer = {
      layerId: 'upper-rw',
      isReadOnly: false,
      files: new Map()
    };
  }

  addLowerFile(layerIndex: number, path: string, sizeKb: number): void {
    const layer = this.lowerLayers[layerIndex];
    if (layer) {
      layer.files.set(path, { sizeKb, inode: this.nextInode++, isWhiteout: false });
    }
  }

  modifyFile(path: string, appendBytesKb: number): { action: string; copiedKb: number; latencyNs: number } {
    if (this.upperLayer.files.has(path)) {
      const existing = this.upperLayer.files.get(path)!;
      existing.sizeKb += appendBytesKb;
      return { action: 'DIRECT_UPPER_WRITE', copiedKb: 0, latencyNs: 25 };
    }

    for (let i = this.lowerLayers.length - 1; i >= 0; i--) {
      const lowerFile = this.lowerLayers[i].files.get(path);
      if (lowerFile && !lowerFile.isWhiteout) {
        const copiedSize = lowerFile.sizeKb + appendBytesKb;
        this.upperLayer.files.set(path, {
          sizeKb: copiedSize,
          inode: this.nextInode++,
          isWhiteout: false
        });
        return { action: 'COPY_ON_WRITE', copiedKb: lowerFile.sizeKb, latencyNs: 120 };
      }
    }

    this.upperLayer.files.set(path, { sizeKb: appendBytesKb, inode: this.nextInode++, isWhiteout: false });
    return { action: 'NEW_UPPER_CREATION', copiedKb: 0, latencyNs: 40 };
  }

  deleteFile(path: string): { whiteoutCreated: boolean } {
    let existsInLower = false;
    for (const lower of this.lowerLayers) {
      if (lower.files.has(path)) { existsInLower = true; break; }
    }
    if (existsInLower) {
      this.upperLayer.files.set(path, { sizeKb: 0, inode: this.nextInode++, isWhiteout: true });
      return { whiteoutCreated: true };
    }
    this.upperLayer.files.delete(path);
    return { whiteoutCreated: false };
  }

  getMergedView(): { totalVisible: number; whiteoutCount: number } {
    const visible = new Set<string>();
    let whiteouts = 0;
    for (const [path, meta] of this.upperLayer.files.entries()) {
      if (meta.isWhiteout) { whiteouts++; }
      else { visible.add(path); }
    }
    for (let i = this.lowerLayers.length - 1; i >= 0; i--) {
      for (const [path, meta] of this.lowerLayers[i].files.entries()) {
        if (!this.upperLayer.files.has(path) && !meta.isWhiteout) {
          visible.add(path);
        }
      }
    }
    return { totalVisible: visible.size, whiteoutCount: whiteouts };
  }
}

