interface BuildGraphNode {
  id: string;
  dependencies: string[];
  isCacheHit: boolean;
  mountType?: 'secret' | 'cache' | 'ssh' | 'none';
  durationMs: number;
}

class BuildKitDAGEngine {
  private nodes: Map<string, BuildGraphNode> = new Map();

  addStage(node: BuildGraphNode): void {
    this.nodes.set(node.id, node);
  }

  simulateParallelBuild(): { totalDurationMs: number; cacheHits: number; secretExposed: boolean } {
    let cacheHitCount = 0;
    let secretLeaked = false;
    let maxParallelDuration = 0;

    const parallelStages = ['build-frontend', 'build-backend', 'fetch-base-layers'];
    let parallelBatchDuration = 0;

    for (const [id, node] of this.nodes.entries()) {
      if (node.isCacheHit) {
        cacheHitCount++;
      }
      if (node.mountType === 'secret') {
        secretLeaked = false;
      }
      if (parallelStages.includes(id)) {
        const effective = node.isCacheHit ? 40 : node.durationMs;
        if (effective > parallelBatchDuration) {
          parallelBatchDuration = effective;
        }
      }
    }

    const finalAssemblyNode = this.nodes.get('export-oci-manifest');
    const finalDuration = finalAssemblyNode ? finalAssemblyNode.durationMs : 120;
    const totalDuration = parallelBatchDuration + finalDuration;

    return {
      totalDurationMs: totalDuration,
      cacheHits: cacheHitCount,
      secretExposed: secretLeaked
    };
  }
}

