interface SyscallPolicy {
  syscallName: string;
  action: 'ALLOW' | 'ERRNO_EPERM' | 'KILL_PROCESS';
}

class SeccompFilterEngine {
  private whitelist: Set<string> = new Set();
  private droppedCaps: Set<string> = new Set();

  constructor(allowedSyscalls: string[], droppedCapabilities: string[]) {
    for (const sc of allowedSyscalls) {
      this.whitelist.add(sc);
    }
    for (const cap of droppedCapabilities) {
      this.droppedCaps.add(cap);
    }
  }

  evaluateSyscall(name: string): { verdict: 'ALLOW' | 'BLOCKED'; action: string } {
    if (this.whitelist.has(name)) {
      return { verdict: 'ALLOW', action: 'SECCOMP_RET_ALLOW' };
    }
    return { verdict: 'BLOCKED', action: 'SECCOMP_RET_KILL_PROCESS' };
  }

  isCapabilityActive(cap: string): boolean {
    return !this.droppedCaps.has(cap);
  }
}

