class KubeApiServerPipeline {
  private validTokens: Map<string, string> = new Map([
    ['bearer-token-dev-123', 'alice-developer'],
    ['bearer-token-ci-999', 'gitlab-runner-sa']
  ]);

  private rbacRules: Set<string> = new Set([
    'alice-developer:create:deployments',
    'gitlab-runner-sa:create:deployments'
  ]);

  processRequest(req: ApiRequest): { status: string; admitted: boolean; latencyMs: number; details: string } {
    // Phase 1: Authentication
    const authenticatedUser = this.validTokens.get(req.token);
    if (!authenticatedUser) {
      return { status: '401_UNAUTHORIZED', admitted: false, latencyMs: 1, details: 'Authentication failed' };
    }

    // Phase 2: Authorization (RBAC)
    const rbacKey = `${authenticatedUser}:${req.verb}:${req.resource}`;
    if (!this.rbacRules.has(rbacKey)) {
      return { status: '403_FORBIDDEN', admitted: false, latencyMs: 2, details: 'RBAC denial' };
    }

    // Phase 3: Mutating Admission Webhook (Inject Sidecar)
    const mutatedBody = { ...req.body };
    if (!mutatedBody.sidecarInjected) {
      mutatedBody.sidecarInjected = true;
      mutatedBody.memoryLimitMb = 512;
    }

    // Phase 4: Validating Admission Webhook (Deny 'latest' tag)
    if (mutatedBody.image.endsWith(':latest')) {
      return { status: '422_VALIDATION_FAILED', admitted: false, latencyMs: 3, details: 'Image tag latest forbidden' };
    }

    return {
      status: '201_CREATED',
      admitted: true,
      latencyMs: 4,
      details: 'Object persisted to etcd with injected sidecar'
    };
  }
}

