interface EtcdRevisionRecord {
  key: string;
  value: string;
  createRevision: number;
  modRevision: number;
  version: number;
  isTombstone: boolean;
}

class EtcdMvccEngine {
  private currentRevision = 1000;
  private boltDbStore: Map<string, EtcdRevisionRecord[]> = new Map();
  private activeWatchers: Map<string, ((event: string) => void)[]> = new Map();

  put(key: string, value: string): EtcdRevisionRecord {
    this.currentRevision++;
    const history = this.boltDbStore.get(key) || [];
    const version = history.length + 1;
    const createRev = history.length > 0 ? history[0].createRevision : this.currentRevision;

    const record: EtcdRevisionRecord = {
      key,
      value,
      createRevision: createRev,
      modRevision: this.currentRevision,
      version,
      isTombstone: false
    };

    history.push(record);
    this.boltDbStore.set(key, history);
    this.notifyWatchers(key, `PUT revision=${this.currentRevision}`);
    return record;
  }

  watch(prefix: string, cb: (event: string) => void): void {
    const watchers = this.activeWatchers.get(prefix) || [];
    watchers.push(cb);
    this.activeWatchers.set(prefix, watchers);
  }

  private notifyWatchers(key: string, event: string): number {
    let dispatched = 0;
    for (const [prefix, callbacks] of this.activeWatchers.entries()) {
      if (key.startsWith(prefix)) {
        for (const cb of callbacks) {
          cb(event);
          dispatched++;
        }
      }
    }
    return dispatched;
  }

  compact(targetRevision: number): number {
    let purged = 0;
    for (const [key, history] of this.boltDbStore.entries()) {
      const filtered = history.filter(h => h.modRevision >= targetRevision);
      purged += (history.length - filtered.length);
      this.boltDbStore.set(key, filtered);
    }
    return purged;
  }

  getCurrentRevision(): number {
    return this.currentRevision;
  }
}

