interface WorkerNode {
  name: string;
  zone: string;
  allocatableMemoryMb: number;
  requestedMemoryMb: number;
  taints: string[];
  cachedImages: string[];
}

interface PodSpec {
  id: string;
  requiredMemoryMb: number;
  tolerations: string[];
  preferredZone: string;
  image: string;
}

class KubeSchedulerEngine {
  schedule(pod: PodSpec, nodes: WorkerNode[]): { feasibleNodes: number; bestNode: string; highestScore: number } {
    // Phase 1: Filtering (Predicates)
    const feasibleNodes = nodes.filter(node => {
      // Predicate 1: NodeResourcesFit
      const availableMemory = node.allocatableMemoryMb - node.requestedMemoryMb;
      if (availableMemory < pod.requiredMemoryMb) return false;

      // Predicate 2: Taints & Tolerations
      for (const taint of node.taints) {
        if (!pod.tolerations.includes(taint)) return false;
      }
      return true;
    });

    if (feasibleNodes.length === 0) {
      return { feasibleNodes: 0, bestNode: 'NONE_PENDING', highestScore: 0 };
    }

    // Phase 2: Scoring (Priorities)
    let bestNodeName = '';
    let maxScore = -1;

    for (const node of feasibleNodes) {
      let score = 50; // baseline

      // Priority 1: Zone affinity
      if (node.zone === pod.preferredZone) score += 30;

      // Priority 2: Image locality
      if (node.cachedImages.includes(pod.image)) score += 14;

      if (score > maxScore) {
        maxScore = score;
        bestNodeName = node.name;
      }
    }

    return {
      feasibleNodes: feasibleNodes.length,
      bestNode: bestNodeName,
      highestScore: maxScore
    };
  }
}

