interface ServiceEndpoint {
  ip: string;
  port: number;
  activeConnections: number;
}

class KubeProxyBenchmarkSimulator {
  private endpoints: ServiceEndpoint[] = [];

  constructor(endpointCount: number) {
    for (let i = 0; i < endpointCount; i++) {
      this.endpoints.push({
        ip: `10.244.${Math.floor(i / 250)}.${i % 250}`,
        port: 8080,
        activeConnections: Math.floor(Math.random() * 50)
      });
    }
  }

  simulateIptablesLookupNs(): number {
    // O(N) sequential rule chain traversal
    // Each rule evaluation incurs ~0.37 ns of memory access
    const count = this.endpoints.length;
    return Math.round(count * 0.37);
  }

  simulateIpvsLookupNs(): number {
    // O(1) hash table lookup via Linux kernel IPVS
    return 42;
  }

  selectLeastConnBackend(): ServiceEndpoint {
    let least = this.endpoints[0];
    for (let i = 1; i < this.endpoints.length; i++) {
      if (this.endpoints[i].activeConnections < least.activeConnections) {
        least = this.endpoints[i];
      }
    }
    return least;
  }
}

