  resolveQuery(domain: string, ndots: number, hasNodeLocalDns: boolean): DnsResolutionProfile {
    const dotCount = (domain.match(/\./g) || []).length;
    let queries = 1;

    if (dotCount < ndots && !domain.endsWith('.')) {
      // Amplification: 3 search domains + 1 absolute query
      queries = 5;
    }

    let savedLatency = 0;
    if (hasNodeLocalDns) {
      // NodeLocal cache reduces 15ms remote latency to 1ms local RAM lookup
      savedLatency = 14;
      queries = 1; // Served from local node cache
    }

    return {
      domain,
      dotCount,
      ndotsConfig: ndots,
      queriesExecuted: queries,
      latencySavedMs: savedLatency
    };
  }
}

