class IstioMeshSecurityManager {
  generateSpiffeId(id: SpiffeIdentity): string {
    return `spiffe://${id.trustDomain}/ns/${id.namespace}/sa/${id.serviceAccount}`;
  }

  executeMtlsHandshake(client: SpiffeIdentity, server: SpiffeIdentity, isStrictMode: boolean): MutualTlsConnection {
    const clientUri = this.generateSpiffeId(client);
