    if (!nsAllowed) {
      return { permitted: false, reason: 'TARGET_NAMESPACE_UNAUTHORIZED', actionVerdict: 'DENIED' };
    }

    return {
      permitted: true,
      reason: 'POLICY_CONFORMS_TO_ENTERPRISE_RBAC',
